import { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import gameService from "../../services/gameService";
import WheelGamePreview from '../../img/WheelGamePreview.jpg';

function GamesPreview() {
    // Состояние для данных
    const [games, setGames] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    
    // Если нужно использовать данные пользователя
    const { currentUser } = useAuth();
    
    // Функция загрузки данных
    const loadGames = async () => {
        try {
            setLoading(true);
            setError(null);
            
            const data = await gameService.getUserGames();
            setGames(data.games || []);
            
        } catch (err) {
            setError('Не удалось загрузить игры');
            console.error('Ошибка загрузки:', err);
        } finally {
            setLoading(false);
        }
    };
    
    // Загружаем данные при монтировании
    useEffect(() => {
        loadGames();
    }, []);
    
    // Кнопка обновления
    const refreshGames = () => {
        loadGames();
    };
    
    // Обработка состояний
    if (loading) {
        return <div>Загрузка игр...</div>;
    }
    
    if (error) {
        return (
            <div>
                <div>Ошибка: {error}</div>
                <button onClick={refreshGames}>Повторить</button>
            </div>
        );
    }
    
    if (games.length === 0) {
        return (
            <div>
                <h1>Мои игры</h1>
                <p>У вас пока нет сохраненных игр</p>
                <button onClick={refreshGames}>Обновить</button>
            </div>
        );
    }
    
    // Отображение списка игр
    return (
        <div className="games-preview">
            <h1>Мои игры</h1>
            <button onClick={refreshGames}>Обновить</button>
            
            {games.map(game => (
                <div key={game.id} className="game-card">
                    <h3>{game.game_name}</h3>
                    <p><strong>Тип:</strong> {game.game_type}</p>
                    <p><strong>Создано:</strong> {game.created_at}</p>
                    <img 
                        src={WheelGamePreview} 
                        alt={`${game.game_name} preview`}
                        style={{
                        width: '200px', 
                        height: '150px', 
                        objectFit: 'cover',
                        borderRadius: '8px',
                         marginBottom: '10px'
                        }}
                    />
                    
                    {/* Если нужно, можно добавить кнопки для действий */}
                    <div className="game-actions">
                        <button onClick={() => console.log('Открыть игру:', game.id)}>
                            Открыть
                        </button>
                        <button onClick={() => console.log('Удалить игру:', game.id)}>
                            Удалить
                        </button>
                    </div>
                </div>
            ))}
        </div>
    );
}

export default GamesPreview;
